"use client";

import { useEffect, useId, useRef, useState, type ReactNode } from "react";
import { FileSearch, RefreshCw } from "lucide-react";
import { useLanguage } from "@/hooks/use-language";
import { cn } from "@/lib/utils";
import { Alert } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

export type RecordDetailMetadata = {
  id: string;
  label: ReactNode;
  value: ReactNode;
  icon?: ReactNode;
};

export type RecordDetailTab = {
  value: string;
  label: ReactNode;
  content: ReactNode;
  icon?: ReactNode;
  count?: number;
  disabled?: boolean;
  keepMounted?: boolean;
};

export type RecordDetailLabels = {
  loading: string;
  refreshing: string;
  errorTitle: string;
  retry: string;
  retryError: string;
  notFoundTitle: string;
  notFoundDescription: string;
  tabs: string;
};

export type GenericRecordDetailProps = {
  title: ReactNode;
  subtitle?: ReactNode;
  eyebrow?: ReactNode;
  avatar?: ReactNode;
  status?: ReactNode;
  metadata?: readonly RecordDetailMetadata[];
  actions?: ReactNode;
  backAction?: ReactNode;
  tabs?: readonly RecordDetailTab[];
  activeTab?: string;
  defaultTab?: string;
  onTabChange?: (value: string) => void;
  children?: ReactNode;
  relatedContent?: ReactNode;
  loading?: boolean;
  error?: string | null;
  onRetry?: () => void | Promise<void>;
  notFound?: boolean;
  notFoundAction?: ReactNode;
  labels?: Partial<RecordDetailLabels>;
  className?: string;
};

/** Presentation and UI state only. Data, permissions and mutations stay with the caller. */
export function GenericRecordDetail({
  title,
  subtitle,
  eyebrow,
  avatar,
  status,
  metadata = [],
  actions,
  backAction,
  tabs = [],
  activeTab,
  defaultTab,
  onTabChange,
  children,
  relatedContent,
  loading = false,
  error,
  onRetry,
  notFound = false,
  notFoundAction,
  labels,
  className,
}: GenericRecordDetailProps) {
  const { l } = useLanguage();
  const headingId = useId();
  const retryPending = useRef(false);
  const [retrying, setRetrying] = useState(false);
  const [retryError, setRetryError] = useState<string | null>(null);
  useEffect(() => setRetryError(null), [error]);
  const copy: RecordDetailLabels = {
    loading: l("Loading record…", "Cargando registro…"),
    refreshing: l("Updating record…", "Actualizando registro…"),
    errorTitle: l("Something needs attention", "Algo necesita atención"),
    retry: l("Try again", "Intentar de nuevo"),
    retryError: l(
      "The record could not be loaded. Please try again.",
      "No se pudo cargar el registro. Intenta de nuevo.",
    ),
    notFoundTitle: l("Record not found", "Registro no encontrado"),
    notFoundDescription: l(
      "This record may have been removed, or you may not have access to it.",
      "Es posible que este registro se haya eliminado o que no tengas acceso.",
    ),
    tabs: l("Record sections", "Secciones del registro"),
    ...labels,
  };
  const hasContent =
    children != null ||
    tabs.length > 0 ||
    metadata.length > 0 ||
    avatar != null;
  const initialLoading = loading && !hasContent;
  const missing = notFound && !loading;
  const problem = retryError || error;
  const firstTab = tabs.find((tab) => !tab.disabled)?.value;
  const initialTab = tabs.some(
    (tab) => tab.value === defaultTab && !tab.disabled,
  )
    ? defaultTab
    : firstTab;
  const selectedTab =
    activeTab === undefined
      ? undefined
      : tabs.some((tab) => tab.value === activeTab && !tab.disabled)
        ? activeTab
        : firstTab;

  const retry = async () => {
    if (!onRetry || retryPending.current || loading) return;
    retryPending.current = true;
    setRetrying(true);
    setRetryError(null);
    try {
      await onRetry();
    } catch (cause) {
      setRetryError(
        cause instanceof Error && cause.message
          ? cause.message
          : copy.retryError,
      );
    } finally {
      retryPending.current = false;
      setRetrying(false);
    }
  };

  return (
    <section
      aria-labelledby={headingId}
      aria-busy={loading || retrying}
      className={cn("grid min-w-0 gap-5 sm:gap-6", className)}
      data-slot="record-detail"
    >
      {backAction && <div className="flex min-w-0">{backAction}</div>}
      {initialLoading ? (
        <Card appearance="flat" className="p-5 sm:p-7">
          <h1 id={headingId} className="sr-only">
            {copy.loading}
          </h1>
          <p role="status" className="mb-5 text-sm text-muted-foreground">
            {copy.loading}
          </p>
          <div className="flex items-center gap-4">
            <Skeleton className="size-16 shrink-0 rounded-2xl" />
            <div className="grid w-full max-w-md gap-3">
              <Skeleton className="h-7 w-3/4" />
              <Skeleton className="h-4 w-full" />
            </div>
          </div>
          <div className="mt-8 grid gap-4 sm:grid-cols-3">
            {[0, 1, 2].map((item) => (
              <Skeleton key={item} className="h-24" />
            ))}
          </div>
        </Card>
      ) : missing ? (
        <Card
          appearance="flat"
          className="flex flex-col items-center gap-4 px-5 py-14 text-center"
        >
          <span
            aria-hidden="true"
            className="flex size-12 items-center justify-center rounded-2xl border border-border bg-surface-subtle text-muted-foreground"
          >
            <FileSearch className="size-5" />
          </span>
          <h1 id={headingId} className="text-xl font-semibold tracking-tight">
            {copy.notFoundTitle}
          </h1>
          <p className="max-w-md text-sm leading-7 text-muted-foreground">
            {copy.notFoundDescription}
          </p>
          {notFoundAction && <div className="mt-2">{notFoundAction}</div>}
        </Card>
      ) : (
        <Card appearance="gradient" className="overflow-hidden p-5 sm:p-7">
          {eyebrow && (
            <p className="mb-5 text-[11px] font-semibold tracking-[.1em] text-primary uppercase">
              {eyebrow}
            </p>
          )}
          <div className="flex min-w-0 flex-col gap-5 sm:flex-row sm:items-start">
            <div className="flex min-w-0 flex-1 items-start gap-4">
              {avatar && <div className="shrink-0">{avatar}</div>}
              <div className="min-w-0">
                <div className="flex min-w-0 flex-wrap items-center gap-3">
                  <h1
                    id={headingId}
                    className="min-w-0 text-[28px] leading-tight font-semibold tracking-[-.035em] break-words sm:text-[34px]"
                  >
                    {title}
                  </h1>
                  {status}
                </div>
                {subtitle && (
                  <p className="mt-2 text-[13px] leading-6 break-words text-muted-foreground">
                    {subtitle}
                  </p>
                )}
              </div>
            </div>
            {actions && (
              <div className="flex flex-wrap items-center gap-2 sm:justify-end">
                {actions}
              </div>
            )}
          </div>
          {metadata.length > 0 && (
            <dl className="mt-6 grid min-w-0 grid-cols-2 gap-x-5 gap-y-5 border-t border-border/70 pt-5 lg:grid-cols-4">
              {metadata.map((item) => (
                <div key={item.id} className="min-w-0">
                  <dt className="flex items-center gap-2 text-[11px] text-muted-foreground">
                    {item.icon && (
                      <span aria-hidden="true" className="[&_svg]:size-3.5">
                        {item.icon}
                      </span>
                    )}
                    {item.label}
                  </dt>
                  <dd className="mt-2 text-sm font-semibold break-words">
                    {item.value ?? "—"}
                  </dd>
                </div>
              ))}
            </dl>
          )}
        </Card>
      )}

      {loading && hasContent && !missing && (
        <p role="status" className="text-xs text-muted-foreground">
          {copy.refreshing}
        </p>
      )}
      {problem && (
        <div className="grid gap-3">
          <Alert variant="destructive" title={copy.errorTitle}>
            {problem}
          </Alert>
          {onRetry && (
            <div>
              <Button
                type="button"
                variant="outline"
                onClick={() => void retry()}
                loading={retrying}
                disabled={loading}
              >
                <RefreshCw aria-hidden="true" />
                {copy.retry}
              </Button>
            </div>
          )}
        </div>
      )}
      {!initialLoading && !missing && (
        <>
          {tabs.length > 0 ? (
            <Tabs
              className="min-w-0 max-w-full"
              value={selectedTab}
              defaultValue={initialTab}
              onValueChange={(value) => onTabChange?.(String(value))}
            >
              <TabsList
                aria-label={copy.tabs}
                className="w-full justify-start sm:w-auto"
              >
                {tabs.map((tab) => (
                  <TabsTrigger
                    key={tab.value}
                    value={tab.value}
                    disabled={tab.disabled}
                  >
                    {tab.icon && <span aria-hidden="true">{tab.icon}</span>}
                    {tab.label}
                    {tab.count !== undefined && (
                      <span className="rounded-md bg-surface-subtle px-1.5 py-0.5 text-[10px] tabular-nums">
                        {tab.count}
                      </span>
                    )}
                  </TabsTrigger>
                ))}
              </TabsList>
              {tabs.map((tab) => (
                <TabsContent
                  key={tab.value}
                  value={tab.value}
                  keepMounted={tab.keepMounted ?? true}
                >
                  {tab.content}
                </TabsContent>
              ))}
            </Tabs>
          ) : (
            children
          )}
          {relatedContent}
        </>
      )}
    </section>
  );
}

"use client";

import Link from "next/link";
import {
  useEffect,
  useId,
  useMemo,
  useRef,
  useState,
  type FormEvent,
  type ReactNode,
} from "react";
import { Controller, useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { z } from "zod";
import {
  Activity,
  ArrowLeft,
  ArrowUpRight,
  Building2,
  CalendarDays,
  CreditCard,
  FileText,
  FolderOpen,
  LayoutDashboard,
  LockKeyhole,
  Mail,
  MessageSquare,
  Paperclip,
  Pencil,
  Receipt,
  Save,
  Send,
} from "lucide-react";
import type { Customer } from "@/demo/dashboard-data";
import { useLanguage } from "@/hooks/use-language";
import {
  GenericRecordDetail,
  type RecordDetailTab,
} from "@/components/blocks/record-detail";
import { Alert } from "@/components/ui/alert";
import { Avatar } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button, buttonVariants } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Empty } from "@/components/ui/empty";
import { Field } from "@/components/ui/field";
import { FileUpload } from "@/components/ui/file-upload";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { TextLink } from "@/components/ui/link";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

export type CustomerDetailNote = {
  id: string;
  text: string;
  author: string;
  authorAvatarSrc?: string;
  createdAt: string;
};

export type CustomerDetailActivity = {
  id: string;
  actor: string;
  detail: string;
  occurredAt: string;
};

export type CustomerDetailInvoice = {
  id: string;
  name?: string;
  number?: string;
  amount: number;
  status: string;
  date?: string;
  href?: string;
};

export type CustomerDetailFile = {
  id: string;
  name: string;
  size?: number;
  type?: string;
  createdAt?: string;
  url?: string;
};

export type CustomerDetailTemplateProps = {
  customer: Customer | null;
  avatarSrc?: string;
  loading?: boolean;
  error?: string | null;
  canEdit?: boolean;
  onSave?: (customer: Customer) => void | Promise<void>;
  notes: readonly CustomerDetailNote[];
  onAddNote?: (text: string) => void | Promise<void>;
  activity: readonly CustomerDetailActivity[];
  relatedInvoices?: readonly CustomerDetailInvoice[];
  attachedFiles?: readonly CustomerDetailFile[];
  filesDescription?: ReactNode;
  onAttach?: (files: File[]) => void | Promise<void>;
  backHref?: string;
  onBack?: () => void;
  onRetry?: () => void | Promise<void>;
};

type Localize = (en: string, es: string) => string;

export function createCustomerDetailSchema(l: Localize = (en) => en) {
  return z.object({
    name: z
      .string()
      .trim()
      .min(2, l("Use at least two characters.", "Usa al menos dos caracteres."))
      .max(
        120,
        l("Use at most 120 characters.", "Usa como máximo 120 caracteres."),
      ),
    email: z
      .string()
      .trim()
      .max(
        254,
        l("Use at most 254 characters.", "Usa como máximo 254 caracteres."),
      )
      .pipe(
        z.email(l("Enter a valid email address.", "Escribe un correo válido.")),
      ),
    company: z
      .string()
      .trim()
      .max(
        200,
        l("Use at most 200 characters.", "Usa como máximo 200 caracteres."),
      ),
    plan: z
      .string()
      .trim()
      .min(1, l("Choose a plan.", "Elige un plan."))
      .max(
        60,
        l("Use at most 60 characters.", "Usa como máximo 60 caracteres."),
      ),
    status: z
      .string()
      .trim()
      .min(1, l("Choose a status.", "Elige un estado."))
      .max(
        60,
        l("Use at most 60 characters.", "Usa como máximo 60 caracteres."),
      ),
    amount: z
      .number({
        error: l("Enter a valid amount.", "Escribe un importe válido."),
      })
      .finite(l("Enter a valid amount.", "Escribe un importe válido."))
      .min(
        0,
        l(
          "The amount cannot be negative.",
          "El importe no puede ser negativo.",
        ),
      ),
  });
}

export type CustomerDetailValues = z.infer<
  ReturnType<typeof createCustomerDetailSchema>
>;

/** Only editable fields are merged; a draft cannot change record identity or join date. */
export function buildCustomerUpdate(
  customer: Customer,
  draft: CustomerDetailValues,
): Customer {
  return {
    ...customer,
    name: draft.name,
    email: draft.email,
    company: draft.company,
    plan: draft.plan,
    status: draft.status,
    amount: draft.amount,
  };
}

function draftFromCustomer(customer: Customer): CustomerDetailValues {
  return {
    name: customer.name,
    email: customer.email,
    company: customer.company,
    plan: customer.plan,
    status: customer.status,
    amount: customer.amount,
  };
}

function failureMessage(cause: unknown, fallback: string) {
  return cause instanceof Error && cause.message ? cause.message : fallback;
}

function timestamp(value: string) {
  const time = new Date(value).getTime();
  return Number.isFinite(time) ? time : 0;
}

function useDetailFormatting() {
  const language = useLanguage();
  const money = (amount: number) =>
    language.number(amount, {
      style: "currency",
      currency: "USD",
      maximumFractionDigits: 2,
    });
  const date = (value: string, withTime = false) => {
    if (!Number.isFinite(new Date(value).getTime()))
      return language.l("Date unavailable", "Fecha no disponible");
    return language.date(value, {
      month: "short",
      day: "numeric",
      year: "numeric",
      ...(value.length === 10 ? {} : { timeZone: "UTC" }),
      ...(withTime
        ? ({
            hour: "numeric",
            minute: "2-digit",
            timeZoneName: "short",
          } as const)
        : {}),
    });
  };
  return { ...language, money, date };
}

function statusLabel(value: string, l: Localize) {
  const labels: Record<string, string> = {
    active: l("Active", "Activo"),
    trial: l("Trial", "Prueba"),
    paused: l("Paused", "Pausado"),
    paid: l("Paid", "Pagada"),
    pending: l("Pending", "Pendiente"),
    overdue: l("Overdue", "Vencida"),
    draft: l("Draft", "Borrador"),
  };
  return labels[value] ?? value;
}

function StatusBadge({ value }: { value: string }) {
  const { l } = useLanguage();
  return (
    <Badge
      className="min-w-0 max-w-full whitespace-normal"
      variant={
        value === "trial" || value === "pending"
          ? "warning"
          : value === "overdue"
            ? "destructive"
            : value === "paused" || value === "draft"
              ? "neutral"
              : "default"
      }
    >
      <span
        aria-hidden="true"
        className="size-1.5 shrink-0 rounded-full bg-current"
      />
      <span className="min-w-0 break-words">{statusLabel(value, l)}</span>
    </Badge>
  );
}

function BackAction({
  backHref,
  onBack,
}: Pick<CustomerDetailTemplateProps, "backHref" | "onBack">) {
  const { l } = useLanguage();
  const label = l("Back to customers", "Volver a clientes");
  if (onBack) {
    return (
      <Button type="button" variant="ghost" size="sm" onClick={onBack}>
        <ArrowLeft aria-hidden="true" />
        {label}
      </Button>
    );
  }
  if (backHref) {
    return (
      <Link
        href={backHref}
        className={buttonVariants({ variant: "ghost", size: "sm" })}
      >
        <ArrowLeft aria-hidden="true" />
        {label}
      </Link>
    );
  }
  return null;
}

export function CustomerDetailTemplate(props: CustomerDetailTemplateProps) {
  const { l } = useLanguage();
  const back =
    props.backHref || props.onBack ? (
      <BackAction backHref={props.backHref} onBack={props.onBack} />
    ) : undefined;
  if (!props.customer) {
    return (
      <GenericRecordDetail
        title={l("Customer", "Cliente")}
        loading={props.loading}
        error={props.error}
        onRetry={props.onRetry}
        notFound={!props.loading && !props.error}
        notFoundAction={back}
        backAction={props.loading || props.error ? back : undefined}
        labels={{
          loading: l("Loading customer…", "Cargando cliente…"),
          errorTitle: l(
            "Could not load this customer",
            "No se pudo cargar este cliente",
          ),
          notFoundTitle: l("Customer not found", "Cliente no encontrado"),
          notFoundDescription: l(
            "This customer may have been removed, or you may not have access. Return to the customer list to continue.",
            "Es posible que este cliente se haya eliminado o que no tengas acceso. Vuelve a la lista de clientes para continuar.",
          ),
        }}
      />
    );
  }
  return (
    <CustomerDetailBody
      key={props.customer.id}
      {...props}
      customer={props.customer}
      backAction={back}
    />
  );
}

function CustomerDetailBody({
  customer,
  avatarSrc,
  loading = false,
  error,
  canEdit = true,
  onSave,
  notes,
  onAddNote,
  activity,
  relatedInvoices = [],
  attachedFiles = [],
  filesDescription,
  onAttach,
  onRetry,
  backAction,
}: CustomerDetailTemplateProps & {
  customer: Customer;
  backAction?: ReactNode;
}) {
  const { l, money, date } = useDetailFormatting();
  const formId = useId();
  const editButton = useRef<HTMLButtonElement>(null);
  const editor = useRef<HTMLFormElement>(null);
  const savePending = useRef(false);
  const returnToEdit = useRef(false);
  const failedSubmitFocus = useRef<HTMLElement | null>(null);
  const [activeTab, setActiveTab] = useState("summary");
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const schema = useMemo(() => createCustomerDetailSchema(l), [l]);
  const form = useForm<CustomerDetailValues>({
    resolver: zodResolver(schema),
    defaultValues: draftFromCustomer(customer),
  });
  const { setFocus } = form;
  const rootError = form.formState.errors.root?.message;
  const busy = saving || form.formState.isSubmitting;
  const mayEdit = canEdit && !!onSave;
  const orderedActivity = [...activity].sort(
    (a, b) => timestamp(b.occurredAt) - timestamp(a.occurredAt),
  );

  useEffect(() => {
    if (editing) setFocus("name");
    else if (returnToEdit.current) {
      editButton.current?.focus();
      returnToEdit.current = false;
    }
  }, [editing, setFocus]);

  useEffect(() => {
    if (!busy && rootError && failedSubmitFocus.current) {
      failedSubmitFocus.current.focus();
      failedSubmitFocus.current = null;
    }
  }, [busy, rootError]);

  const beginEditing = () => {
    if (!mayEdit || loading) return;
    form.reset(draftFromCustomer(customer));
    setSaved(false);
    setActiveTab("summary");
    setEditing(true);
  };
  const cancel = () => {
    if (savePending.current) return;
    form.reset(draftFromCustomer(customer));
    returnToEdit.current = true;
    setEditing(false);
  };
  const submit = (event: FormEvent<HTMLFormElement>) =>
    form.handleSubmit(
      async (values) => {
        if (!canEdit || !onSave || loading || savePending.current) return;
        savePending.current = true;
        setSaving(true);
        setSaved(false);
        const focused = document.activeElement;
        const focusTarget =
          focused instanceof HTMLElement && editor.current?.contains(focused)
            ? focused
            : null;
        try {
          await onSave(buildCustomerUpdate(customer, values));
          form.reset(values);
          returnToEdit.current = true;
          setEditing(false);
          setSaved(true);
        } catch (cause) {
          form.setError("root", {
            type: "server",
            message: failureMessage(
              cause,
              l(
                "Your changes could not be saved. Your draft is still here.",
                "No se pudieron guardar los cambios. Tu borrador sigue aquí.",
              ),
            ),
          });
          failedSubmitFocus.current = focusTarget;
        } finally {
          savePending.current = false;
          setSaving(false);
        }
      },
      (errors) => {
        const first = Object.keys(errors)[0];
        if (first === "plan" || first === "status") {
          document.getElementById(`${formId}-${first}`)?.focus();
        }
      },
    )(event);

  const plans = [...new Set([customer.plan, "Starter", "Pro", "Enterprise"])]
    .filter(Boolean)
    .map((value) => ({ value, label: value }));
  const statuses = [...new Set([customer.status, "active", "trial", "paused"])]
    .filter(Boolean)
    .map((value) => ({ value, label: statusLabel(value, l) }));
  const readOnlyCopy = !canEdit
    ? l(
        "You have read-only access to this customer.",
        "Tienes acceso de solo lectura a este cliente.",
      )
    : l(
        "Customer details are read-only.",
        "Los datos del cliente son de solo lectura.",
      );

  const summary = (
    <div className="grid items-start gap-5 xl:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)]">
      <Card appearance="flat">
        <CardHeader>
          <CardTitle>
            {editing
              ? l("Edit customer details", "Editar datos del cliente")
              : l("Customer details", "Datos del cliente")}
          </CardTitle>
          <CardDescription>
            {editing
              ? l(
                  "Keep contact and account information up to date.",
                  "Mantén al día la información de contacto y de la cuenta.",
                )
              : l(
                  "The essentials for a thoughtful customer relationship.",
                  "Lo esencial para una relación cercana con tu cliente.",
                )}
          </CardDescription>
        </CardHeader>
        <CardContent>
          {editing ? (
            <form
              ref={editor}
              onSubmit={submit}
              noValidate
              aria-busy={busy}
              className="grid gap-5"
            >
              {!mayEdit && (
                <Alert
                  variant="warning"
                  title={l(
