            "Registros de facturación asociados con este cliente.",
          )}
        </CardDescription>
      </CardHeader>
      <CardContent>
        {!invoices.length ? (
          <Empty
            icon={<Receipt aria-hidden="true" />}
            title={l("No related invoices", "No hay facturas relacionadas")}
            description={l(
              "Associated invoices will appear here when available.",
              "Las facturas asociadas aparecerán aquí cuando estén disponibles.",
            )}
            className="py-7"
          />
        ) : (
          <Table
            aria-label={l("Related invoices", "Facturas relacionadas")}
            density="compact"
          >
            <TableHeader>
              <TableRow>
                <TableHead>{l("Invoice", "Factura")}</TableHead>
                <TableHead>{l("Status", "Estado")}</TableHead>
                <TableHead>{l("Date", "Fecha")}</TableHead>
                <TableHead className="text-right">
                  {l("Amount", "Importe")}
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {invoices.map((invoice) => (
                <TableRow key={invoice.id}>
                  <TableCell>
                    {invoice.href ? (
                      <TextLink href={invoice.href}>
                        {invoice.number || invoice.name || invoice.id}
                      </TextLink>
                    ) : (
                      <span className="font-medium">
                        {invoice.number || invoice.name || invoice.id}
                      </span>
                    )}
                  </TableCell>
                  <TableCell>
                    <StatusBadge value={invoice.status} />
                  </TableCell>
                  <TableCell className="whitespace-nowrap text-muted-foreground">
                    {invoice.date ? date(invoice.date) : "—"}
                  </TableCell>
                  <TableCell className="text-right font-medium tabular-nums whitespace-nowrap">
                    {money(invoice.amount)}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </CardContent>
    </Card>
  );
}

import * as React from "react";
import { Info, CircleCheck, TriangleAlert } from "lucide-react";
import { cn } from "@/lib/utils";
export function Alert({
  title,
  children,
  variant = "info",
  className,
}: {
  title: string;
  children?: React.ReactNode;
  variant?: "info" | "success" | "warning" | "destructive";
  className?: string;
}) {
  const Icon =
    variant === "success"
      ? CircleCheck
      : variant === "warning" || variant === "destructive"
        ? TriangleAlert
        : Info;
  return (
    <div
      role={variant === "destructive" ? "alert" : "status"}
      className={cn(
        "flex gap-3 rounded-lg border p-4 text-xs",
        variant === "warning"
          ? "border-warning-foreground/20 bg-warning text-warning-foreground"
          : variant === "destructive"
            ? "border-destructive-foreground/20 bg-destructive text-destructive-foreground"
            : "border-primary/15 bg-accent text-accent-foreground",
        className,
      )}
    >
      <Icon className="mt-0.5 size-4 shrink-0" />
      <div>
        <p className="font-semibold">{title}</p>
        {children && <div className="mt-1 leading-relaxed">{children}</div>}
      </div>
    </div>
  );
}

